// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address newOwner) public {
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            // Rule: ownership transfer to the zero address is never allowed.
            assertTrue(newOwner != address(0) && c.owner() == newOwner);
        } catch {
            assertTrue(newOwner == address(0), "only the zero-address transfer may revert");
        }
    }
}

